    CONSTRAINT checkin_tag_corrections_to_tag_check CHECK (((to_tag IS NULL) OR (to_tag = ANY (ARRAY['M01'::text, 'M02'::text, 'M03'::text, 'M04'::text, 'M05'::text]))))
);

