-- Name: TABLE checkin_tag_corrections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.checkin_tag_corrections IS 'Append-only record of every time the coach changed or rejected a proposed loop tag. from_tag NULL = nothing was proposed; to_tag NULL = no tag was right. Fed back to the generator for THAT CLIENT only. Never updated, never deleted.';

--
-- Name: COLUMN checkin_tag_corrections.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.checkin_tag_corrections.reason IS 'The coach''s own words. Optional, and the highest-value field in the system — it is the difference between the generator learning the rule and learning the label.';

