--
-- Name: client_allergies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_allergies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid,
    submission_id uuid,
    allergen_key text NOT NULL,
    allergen_label text NOT NULL,
    severity text DEFAULT 'unknown'::text NOT NULL,
    reaction text,
    raw_text text,
    source text DEFAULT 'intake'::text NOT NULL,
    confidence text DEFAULT 'parsed'::text NOT NULL,
    needs_review boolean DEFAULT true NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deactivated_at timestamp with time zone,
    deactivated_reason text,
    CONSTRAINT client_allergies_confidence_check CHECK ((confidence = ANY (ARRAY['parsed'::text, 'coach_confirmed'::text, 'client_confirmed'::text]))),
    CONSTRAINT client_allergies_severity_check CHECK ((severity = ANY (ARRAY['unknown'::text, 'intolerance'::text, 'allergy'::text, 'anaphylaxis'::text])))
);

--
-- Name: TABLE client_allergies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_allergies IS 'Structured allergen records. Safety-critical: intended for programmatic meal-plan filtering. Rows created from intake parsing start needs_review=true and confidence=parsed; a filter that must not fail should require confidence <> ''parsed'' or handle needs_review explicitly.';

--
-- Name: COLUMN client_allergies.deactivated_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.client_allergies.deactivated_reason IS 'Why this row was set inactive. Required in practice whenever active is set false: a withdrawn allergy claim without a stated basis is not auditable.';

--
-- Name: client_allergy_confirmations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_allergy_confirmations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    status text NOT NULL,
    confirmed_by_role text NOT NULL,
    confirmed_by uuid,
    confirmed_at timestamp with time zone DEFAULT now() NOT NULL,
    basis text NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by_source text,
    superseded_detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_allergy_confirmations_confirmed_by_role_check CHECK ((confirmed_by_role = ANY (ARRAY['coach'::text, 'client'::text]))),
    CONSTRAINT client_allergy_confirmations_status_check CHECK ((status = 'none_known'::text))
);

--
-- Name: client_checkin_schedule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_checkin_schedule (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    due_on date NOT NULL,
    cadence text NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    checkin_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ccs_cadence_ck CHECK ((cadence = ANY (ARRAY['weekly'::text, 'biweekly'::text, 'monthly'::text]))),
    CONSTRAINT ccs_status_ck CHECK ((status = ANY (ARRAY['scheduled'::text, 'submitted'::text, 'missed'::text, 'cancelled'::text])))
);

--
-- Name: TABLE client_checkin_schedule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_checkin_schedule IS 'One row per expected check-in occurrence, written at onboarding so a new client opens the app to a scheduled rhythm rather than an empty tab. status=''scheduled'' with a past due_on that never became ''submitted'' is a MISSED check-in — a fact about the client, and real signal. Absence of any row is a fact about the SYSTEM (never scheduled). The two are not the same and must never render the same.';

--
-- Name: client_dietary_restrictions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_dietary_restrictions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid,
    submission_id uuid,
    kind text NOT NULL,
    restriction_key text NOT NULL,
    restriction_label text NOT NULL,
    raw_text text,
    source text DEFAULT 'intake'::text NOT NULL,
    confidence text DEFAULT 'parsed'::text NOT NULL,
    needs_review boolean DEFAULT true NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_dietary_restrictions_confidence_check CHECK ((confidence = ANY (ARRAY['parsed'::text, 'coach_confirmed'::text, 'client_confirmed'::text]))),
    CONSTRAINT client_dietary_restrictions_kind_check CHECK ((kind = ANY (ARRAY['pattern'::text, 'exclusion'::text, 'dislike'::text, 'intolerance'::text, 'preference'::text])))
);

--
-- Name: TABLE client_dietary_restrictions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_dietary_restrictions IS 'Structured dietary patterns, exclusions and dislikes. Separate from client_allergies because a dislike is a preference and an allergy is a safety constraint.';

--
-- Name: COLUMN client_dietary_restrictions.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.client_dietary_restrictions.kind IS 'pattern = a diet the meal must satisfy. exclusion = a food the meal must not contain. dislike = a stated aversion. intolerance = a reported digestive reaction. preference = advisory only -- informs how a plan is built, never whether one can be built. Gate C skips preference by design.';

--
-- Name: client_meal_plan_slot_options; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_meal_plan_slot_options (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slot_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    meal_id uuid NOT NULL,
    "position" integer DEFAULT 0 NOT NULL
);

--
-- Name: client_meal_plan_slots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_meal_plan_slots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    day_index integer DEFAULT 0 NOT NULL,
    slot_index integer NOT NULL,
    slot_label text,
    meal_id uuid,
    servings numeric DEFAULT 1 NOT NULL,
    is_locked boolean DEFAULT false NOT NULL,
    note text,
    CONSTRAINT client_meal_plan_slots_servings_check CHECK ((servings > (0)::numeric))
);

--
-- Name: client_meal_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_meal_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    title text,
    status text DEFAULT 'draft'::text NOT NULL,
    assembly_mode text DEFAULT 'rotation'::text NOT NULL,
    rotation_days integer DEFAULT 7 NOT NULL,
    substitution_policy text DEFAULT 'open'::text NOT NULL,
    target_calories numeric,
    target_protein_g numeric,
    target_fat_g numeric,
    target_carb_g numeric,
    meals_per_day integer,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_at timestamp with time zone,
    CONSTRAINT client_meal_plans_assembly_mode_check CHECK ((assembly_mode = ANY (ARRAY['rotation'::text, 'fixed'::text]))),
    CONSTRAINT client_meal_plans_meals_per_day_check CHECK (((meals_per_day >= 1) AND (meals_per_day <= 8))),
    CONSTRAINT client_meal_plans_rotation_days_check CHECK (((rotation_days >= 1) AND (rotation_days <= 28))),
    CONSTRAINT client_meal_plans_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'assigned'::text, 'archived'::text]))),
    CONSTRAINT client_meal_plans_substitution_policy_check CHECK ((substitution_policy = ANY (ARRAY['open'::text, 'limited'::text, 'locked'::text])))
);

--
-- Name: TABLE client_meal_plans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_meal_plans IS 'A client plan is an assembly of selections from public.meals. assembly_mode ''rotation'' = lifestyle (variety, substitutions, multi-day cycle); ''fixed'' = competition prep (same meals repeated, repeatability is the feature). Coexists with the legacy public.meal_plans, which is untouched and still serving live clients.';

--
-- Name: client_notes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    author_user_id uuid,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: client_onboarding; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_onboarding (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    submission_id uuid,
    stage text DEFAULT 'started'::text NOT NULL,
    account_state text DEFAULT 'pending'::text NOT NULL,
    program_draft_id uuid,
    meal_plan_id uuid,
    checkins_scheduled integer DEFAULT 0 NOT NULL,
    blockers jsonb DEFAULT '[]'::jsonb NOT NULL,
    notes text,
    released_at timestamp with time zone,
    released_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT co_account_ck CHECK ((account_state = ANY (ARRAY['pending'::text, 'created'::text, 'existed'::text, 'no_email'::text, 'failed'::text]))),
    CONSTRAINT co_stage_ck CHECK ((stage = ANY (ARRAY['started'::text, 'prepared'::text, 'blocked'::text, 'released'::text])))
);

--
-- Name: TABLE client_onboarding; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_onboarding IS 'One row per intake-to-client onboarding run. Holds the RELEASE GATE: stage only reaches ''released'' when the program draft, the meal plan and the check-in schedule are all ready together, so a client can never sign in and find a program but no food, or food but no check-in. blockers is an array of {code, detail} — each one is a real missing input that a human has to resolve. A blocker is a finding to report, never a value to fill in.';

--
-- Name: COLUMN client_onboarding.blockers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.client_onboarding.blockers IS 'Array of {code, detail, at}. Populated when the pipeline hits missing or unsafe context (unreviewed allergy, ambiguous email match, unstated client_type, thin meal library). The pipeline stops and records the gap rather than producing a plausible plan.';

--
-- Name: clients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clients (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_user_id uuid,
    display_name text NOT NULL,
    status public.client_status DEFAULT 'invited'::public.client_status NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notif_enabled boolean DEFAULT false NOT NULL,
    notif_channels jsonb DEFAULT '{"sms": false, "push": false}'::jsonb NOT NULL,
    push_subscription jsonb,
    phone_e164 text,
    phone_verified_at timestamp with time zone,
    sms_consent_at timestamp with time zone,
    sms_consent_version text,
    welcome_seen boolean DEFAULT false NOT NULL,
    invite_token text,
    invite_expires_at timestamp with time zone,
    email text,
    stripe_customer_id text,
    stripe_subscription_id text,
    subscription_status text,
    coaching_tier text,
    age smallint,
    sex text,
    height_cm numeric(6,2),
    weight_kg numeric(7,3),
    activity_level text,
    body_fat_pct numeric(4,1),
    unit_pref text DEFAULT 'imperial'::text NOT NULL,
    show_date date,
    show_name text,
    pause_resume_date date,
    paused_at timestamp with time zone,
    client_type text,
    checkin_cadence text,
    checkin_day_of_week smallint,
    weight_lb numeric(6,2),
    height_in numeric(5,2),
    goal_weight_lb numeric(6,2),
    goal_weight_kg numeric(7,3),
    CONSTRAINT clients_activity_ck CHECK (((activity_level IS NULL) OR (activity_level = ANY (ARRAY['sedentary'::text, 'light'::text, 'moderate'::text, 'active'::text, 'very_active'::text])))),
    CONSTRAINT clients_age_ck CHECK (((age IS NULL) OR ((age >= 0) AND (age <= 120)))),
    CONSTRAINT clients_bodyfat_ck CHECK (((body_fat_pct IS NULL) OR ((body_fat_pct >= (0)::numeric) AND (body_fat_pct <= (75)::numeric)))),
    CONSTRAINT clients_checkin_cadence_ck CHECK (((checkin_cadence IS NULL) OR (checkin_cadence = ANY (ARRAY['weekly'::text, 'biweekly'::text, 'monthly'::text])))),
    CONSTRAINT clients_checkin_dow_ck CHECK (((checkin_day_of_week IS NULL) OR ((checkin_day_of_week >= 0) AND (checkin_day_of_week <= 6)))),
    CONSTRAINT clients_client_type_ck CHECK (((client_type IS NULL) OR (client_type = ANY (ARRAY['lifestyle'::text, 'prep'::text])))),
    CONSTRAINT clients_coaching_tier_check CHECK ((coaching_tier = ANY (ARRAY['entry'::text, 'standard'::text]))),
    CONSTRAINT clients_sex_ck CHECK (((sex IS NULL) OR (sex = ANY (ARRAY['male'::text, 'female'::text, 'other'::text])))),
    CONSTRAINT clients_unit_pref_ck CHECK ((unit_pref = ANY (ARRAY['imperial'::text, 'metric'::text])))
);

--
-- Name: COLUMN clients.weight_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.weight_kg IS 'DERIVED from weight_lb for Mifflin-St Jeor. Never display this; display weight_lb.';

--
-- Name: COLUMN clients.show_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.show_date IS 'Target competition/photoshoot date. NULL = not a dated client; undated clients are excluded from the Prep rail, never ranked lower on it.';

--
-- Name: COLUMN clients.pause_resume_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.pause_resume_date IS 'Date a paused client is expected back. NULL on a paused client is what the home page flags.';

--
-- Name: COLUMN clients.client_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.client_type IS 'lifestyle or prep. Drives BOTH the program draft and the meal assembly: prep gets repetition and precision (fixed rotation, locked substitutions); lifestyle gets substitution room and a bad-week fallback. NULL means the intake did not state it — that is a gap to resolve with the client, never a value to default. Nothing downstream may assume lifestyle because the column is empty.';

--
-- Name: COLUMN clients.checkin_cadence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.checkin_cadence IS 'Per-client override of tenant_config.checkin_cadence. NULL = inherit the tenant default. Distinct from a zero: NULL is "not set here", not "no check-ins".';

--
-- Name: COLUMN clients.checkin_day_of_week; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.checkin_day_of_week IS '0=Sunday..6=Saturday. The anchor weekday for scheduled check-ins. NULL = inherit the day the client started.';

--
-- Name: COLUMN clients.weight_lb; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.weight_lb IS 'What the client actually typed, in pounds. CANONICAL FOR DISPLAY. weight_kg is derived from this and is for arithmetic only.';

--
-- Name: COLUMN clients.height_in; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.height_in IS 'What the client actually typed, in inches. CANONICAL FOR DISPLAY. height_cm is derived from this.';

--
-- Name: COLUMN clients.goal_weight_lb; Type: COMMENT; Schema: public; Owner: -
--

