--

COMMENT ON TABLE public.meal_tags IS 'Diet/allergen/attribute vocabulary. allergen keys deliberately match public.client_allergies.allergen_key so intake-captured allergies filter the library directly. Same vocabulary on both sides or the filter silently misses.';

