CREATE TABLE public.tenants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coach_user_id uuid,
    slug text NOT NULL,
    plan text DEFAULT 'v1'::text NOT NULL,
    status public.tenant_status DEFAULT 'active'::public.tenant_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    license_stripe_ref text,
    licensed_at timestamp with time zone,
    stripe_customer_id text,
    subscription_id text,
    subscription_status text
);

--
-- Name: trainerize_archive; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trainerize_archive (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    kind text NOT NULL,
    trainerize_id text NOT NULL,
    occurred_at timestamp with time zone,
    payload jsonb NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trainerize_archive_kind_check CHECK ((kind = ANY (ARRAY['workout_session'::text, 'meal'::text])))
);

--
-- Name: trainerize_staging; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trainerize_staging (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    source_client_id text NOT NULL,
    source_client_email text,
    source_client_name text,
    matched_client_id uuid,
    match_status text NOT NULL,
    kind text NOT NULL,
    occurred_at timestamp with time zone,
    payload jsonb NOT NULL,
    promoted_at timestamp with time zone,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trainerize_staging_kind_check CHECK ((kind = ANY (ARRAY['profile'::text, 'consultation'::text, 'workout_session'::text, 'workout_set'::text, 'weight'::text, 'body_measurement'::text, 'progress_photo'::text, 'cardio_activity'::text, 'message'::text, 'nutrition_goal'::text]))),
    CONSTRAINT trainerize_staging_match_status_check CHECK ((match_status = ANY (ARRAY['matched'::text, 'unmatched'::text, 'ambiguous'::text])))
);

--
-- Name: v_pending_program_drafts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pending_program_drafts AS
 SELECT d.id AS draft_id,
    d.tenant_id,
    d.client_id,
    c.display_name,
    c.email,
    d.status,
    d.health_flags,
    d.macros,
    d.rationale,
    d.generated_at,
    jsonb_array_length(COALESCE((d.training -> 'days'::text), '[]'::jsonb)) AS training_days
   FROM (public.program_drafts d
     JOIN public.clients c ON ((c.id = d.client_id)))
  WHERE (d.status = ANY (ARRAY['draft'::public.program_draft_status, 'held_medical'::public.program_draft_status]));

--
-- Name: video_assignment_responses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.video_assignment_responses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    body text NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    coach_seen boolean DEFAULT false NOT NULL,
    CONSTRAINT video_response_body_present CHECK ((length(btrim(body)) > 0))
);

--
-- Name: TABLE video_assignment_responses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.video_assignment_responses IS 'The client''s single text reply to an assignment. Insert-only for clients; coach_seen is coach-writable only.';

--
-- Name: video_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.video_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    video_id uuid,
    video_youtube_id text NOT NULL,
    video_title text NOT NULL,
    prompt text NOT NULL,
    assigned_by uuid,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    due_on date,
    CONSTRAINT video_assignments_prompt_present CHECK ((length(btrim(prompt)) > 0))
);

--
-- Name: TABLE video_assignments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.video_assignments IS 'Coach assigns a shelf video to one client with a prompt. Snapshots video id+title so removing the video does not erase the ask.';

--
-- Name: workout_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workout_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    session_id uuid NOT NULL,
    exercise_id uuid NOT NULL,
    set_index integer NOT NULL,
    weight numeric(6,2),
    reps integer,
    done boolean DEFAULT false NOT NULL,
    logged_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    rpe numeric(3,1),
    CONSTRAINT workout_logs_rpe_check CHECK (((rpe IS NULL) OR ((rpe >= (1)::numeric) AND (rpe <= (10)::numeric))))
);

--
-- Name: COLUMN workout_logs.rpe; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workout_logs.rpe IS 'Rate of perceived exertion, 1.0-10.0. Nullable: historical sets have none and must stay valid.';

--
-- Name: workout_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workout_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    day_id uuid NOT NULL,
    session_date date DEFAULT ((now() AT TIME ZONE 'utc'::text))::date NOT NULL,
    status public.session_status DEFAULT 'in_progress'::public.session_status NOT NULL,
    completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

