INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES
  ('brand', 'brand', true, NULL, NULL),
  ('progress-photos', 'progress-photos', false, NULL, NULL),
  ('resources', 'resources', false, NULL, NULL)
ON CONFLICT (id) DO NOTHING;
-- meal-photos is created by the matching block below (public, 10 MB, images only).
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES
  ('meal-photos', 'meal-photos', true, 10485760, ARRAY['image/jpeg', 'image/png', 'image/webp'])
ON CONFLICT (id) DO NOTHING;

CREATE POLICY brand_coach_update ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'brand'::text) AND (public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)));
CREATE POLICY brand_coach_write ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'brand'::text) AND (public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)));
CREATE POLICY photos_owner_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'progress-photos'::text) AND ((((storage.foldername(name))[1] = (public.current_tenant_id())::text) AND ((storage.foldername(name))[2] = (public.current_client_id())::text)) OR ((public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)))));
CREATE POLICY photos_owner_write ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'progress-photos'::text) AND ((((storage.foldername(name))[1] = (public.current_tenant_id())::text) AND ((storage.foldername(name))[2] = (public.current_client_id())::text)) OR ((public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)))));
CREATE POLICY res_coach_update ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'resources'::text) AND (public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)));
CREATE POLICY res_coach_write ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'resources'::text) AND (public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)));
CREATE POLICY res_owner_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'resources'::text) AND ((((storage.foldername(name))[1] = (public.current_tenant_id())::text) AND ((storage.foldername(name))[2] = (public.current_client_id())::text)) OR ((public.current_app_role() = 'coach'::text) AND ((storage.foldername(name))[1] = (public.current_tenant_id())::text)))));

-- ---------------------------------------------------------------------------
-- Auth triggers: link a confirmed sign-in to an existing client record by email.
-- (auth.users belongs to Supabase; the trigger functions live in public.)
-- ---------------------------------------------------------------------------

DROP TRIGGER IF EXISTS link_client_on_insert ON auth.users;
CREATE TRIGGER link_client_on_insert
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.on_auth_user_confirmed();

DROP TRIGGER IF EXISTS link_client_on_confirm ON auth.users;
CREATE TRIGGER link_client_on_confirm
  AFTER UPDATE OF email_confirmed_at ON auth.users
  FOR EACH ROW
  WHEN (old.email_confirmed_at IS NULL AND new.email_confirmed_at IS NOT NULL)
  EXECUTE FUNCTION public.on_auth_user_confirmed();
